<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { LineChart } from 'echarts/charts';
import { GridComponent, TooltipComponent } from 'echarts/components';
import { init, use, type ECharts } from 'echarts/core';
import { CanvasRenderer } from 'echarts/renderers';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '@/api';
import { useAppStore } from '@/stores/app';
import type { FinanceSummary, FinancialAdjustment, Settlement } from '@/types/domain';
import { money, shanghaiTime } from '@/utils/format';
import AppIcon from '@/components/AppIcon.vue';

use([LineChart, GridComponent, TooltipComponent, CanvasRenderer]);
const appStore = useAppStore(); const loading = ref(false); const summary = ref<FinanceSummary | null>(null); const rows = ref<Settlement[]>([]); const total = ref(0); const chartEl = ref<HTMLElement>(); let chart: ECharts | null = null;
const query = reactive({ keyword: '', page: 1, pageSize: 10 }); const selected = ref<Settlement | null>(null); const drawerOpen = ref(false); const adjustOpen = ref(false); const saving = ref(false);
const form = reactive<{ type: 'charge' | 'credit'; amountYuan: number; reason: string }>({ type: 'credit', amountYuan: 0, reason: '' });
const previewCents = computed(() => selected.value ? selected.value.effectiveAmountCents + (form.type === 'credit' ? -1 : 1) * Math.round(Math.abs(form.amountYuan) * 100) : 0);
async function load() { loading.value = true; try { const scope = appStore.selectedScenicAreaId; const [summaryResult, listResult] = await Promise.all([api.financeSummary(scope), api.settlements({ scenicAreaId: scope, ...query })]); summary.value = summaryResult; rows.value = listResult.items; total.value = listResult.total; await renderChart(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : '财务数据加载失败'); } finally { loading.value = false; } }
async function renderChart() { await nextTick(); if (!chartEl.value || !summary.value) return; chart ||= init(chartEl.value); chart.setOption({ grid: { left: 12, right: 18, top: 20, bottom: 10, containLabel: true }, tooltip: { trigger: 'axis', valueFormatter: (value: any) => money(Number(value)) }, xAxis: { type: 'category', data: summary.value.trend.map((item) => item.date.slice(5)), axisLine: { lineStyle: { color: '#ddd8d1' } }, axisLabel: { color: '#817e78' } }, yAxis: { type: 'value', axisLabel: { formatter: (value: number) => `¥${value / 100}`, color: '#817e78' }, splitLine: { lineStyle: { color: '#eeeae5' } } }, series: [{ type: 'line', smooth: true, symbolSize: 7, data: summary.value.trend.map((item) => item.amountCents), lineStyle: { width: 3, color: '#ef5b24' }, itemStyle: { color: '#ef5b24' }, areaStyle: { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [{ offset: 0, color: 'rgba(239,91,36,.28)' }, { offset: 1, color: 'rgba(239,91,36,.02)' }] } } }] }); }
async function openSettlement(row: Settlement) { selected.value = await api.settlement(row.id); drawerOpen.value = true; }
function startAdjustment() { form.type = 'credit'; form.amountYuan = 0; form.reason = ''; adjustOpen.value = true; }
async function submitAdjustment() { if (!selected.value || form.amountYuan <= 0 || form.reason.trim().length < 4) { ElMessage.warning('请填写有效金额和至少 4 个字的原因'); return; } if (previewCents.value < 0) { ElMessage.error('调账后最终应收不得小于 0'); return; } await ElMessageBox.confirm(`调整前 ${money(selected.value.effectiveAmountCents)}，调整后 ${money(previewCents.value)}。流水保存后不可编辑或删除。`, '调账二次确认', { confirmButtonText: '确认新增流水', cancelButtonText: '取消', type: 'warning' }); saving.value = true; try { selected.value = await api.adjustSettlement(selected.value.id, { type: form.type, amountCents: Math.round(form.amountYuan * 100), reason: form.reason.trim(), idempotencyKey: crypto.randomUUID() }); adjustOpen.value = false; ElMessage.success('调账流水已追加'); await load(); } finally { saving.value = false; } }
async function reverse(adjustment: FinancialAdjustment) { if (!selected.value) return; const { value } = await ElMessageBox.prompt('撤销通过新增反向流水完成，原流水仍会保留。请输入撤销原因：', '撤销调账', { confirmButtonText: '下一步', cancelButtonText: '取消', inputValidator: (text) => String(text || '').trim().length >= 4 || '至少输入 4 个字' }); await ElMessageBox.confirm(`将新增 ${money(-adjustment.amountCents)} 的反向流水，确认继续？`, '撤销二次确认', { type: 'warning', confirmButtonText: '确认撤销' }); selected.value = await api.reverseAdjustment(selected.value.id, adjustment.id, value.trim(), crypto.randomUUID()); ElMessage.success('反向流水已追加'); await load(); }
function isReversed(adjustment: FinancialAdjustment) { return selected.value?.adjustments?.some((item) => item.reversedAdjustmentId === adjustment.id); }
watch(() => appStore.selectedScenicAreaId, () => { query.page = 1; load(); }, { immediate: true }); const resize = () => chart?.resize(); window.addEventListener('resize', resize); onBeforeUnmount(() => { window.removeEventListener('resize', resize); chart?.dispose(); });
</script>

<template>
  <div class="page-stack" v-loading="loading"><el-alert title="演示支付环境" description="当前支付、退款和财务金额均为业务演示数据；不会调用微信支付或真实退款接口。" type="warning" :closable="false" show-icon /><section class="metric-strip" v-if="summary"><article class="metric-card"><div class="metric-icon orange"><AppIcon name="coin" /></div><div><span>原始结算</span><strong>{{ money(summary.originalAmountCents) }}</strong><small>不受调账流水覆盖</small></div></article><article class="metric-card"><div class="metric-icon blue"><AppIcon name="adjustment" /></div><div><span>调账净额</span><strong>{{ money(summary.adjustmentAmountCents) }}</strong><small>追加式不可变流水</small></div></article><article class="metric-card"><div class="metric-icon green"><AppIcon name="trend" /></div><div><span>有效应收</span><strong>{{ money(summary.effectiveAmountCents) }}</strong><small>原始金额 + 有效流水</small></div></article><article class="metric-card"><div class="metric-icon orange"><AppIcon name="receipt" /></div><div><span>结算笔数</span><strong>{{ summary.settlementCount }}</strong><small>当前景区范围</small></div></article></section><section class="panel chart-panel"><div class="panel-title"><div><h2>近 7 日有效结算趋势</h2><p>金额单位为人民币元，数据源更新时间随系统状态栏同步</p></div><el-tag type="warning">DEMO PAY</el-tag></div><div ref="chartEl" class="finance-chart" /></section><section class="panel"><div class="panel-toolbar"><div><h2>结算明细</h2><p>支持追加人工调账和反向撤销，不提供导出</p></div><div class="toolbar-controls"><el-input v-model="query.keyword" placeholder="搜索订单号" clearable style="width:210px" @keyup.enter="load"><template #prefix><AppIcon name="search" /></template></el-input><el-button type="primary" @click="load"><AppIcon name="search" />查询</el-button></div></div><el-table :data="rows" stripe class="data-table"><el-table-column prop="orderNo" label="订单号" min-width="175"><template #default="{ row }"><div class="primary-cell"><strong>{{ row.orderNo }}</strong><el-tag v-if="row.isDemo" size="small" type="warning">演示</el-tag></div></template></el-table-column><el-table-column label="原始金额" width="125"><template #default="{ row }">{{ money(row.originalAmountCents) }}</template></el-table-column><el-table-column label="调账净额" width="125"><template #default="{ row }"><span :class="row.adjustmentAmountCents < 0 ? 'amount-negative' : 'amount-positive'">{{ money(row.adjustmentAmountCents) }}</span></template></el-table-column><el-table-column label="有效应收" width="130"><template #default="{ row }"><strong>{{ money(row.effectiveAmountCents) }}</strong></template></el-table-column><el-table-column label="支付状态" width="120"><template #default><el-tag type="warning" effect="plain">演示已支付</el-tag></template></el-table-column><el-table-column label="结算时间" min-width="175"><template #default="{ row }">{{ shanghaiTime(row.settledAt) }}</template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openSettlement(row)">详情</el-button></template></el-table-column></el-table><div class="pagination-row"><span>共 {{ total }} 条</span><el-pagination v-model:current-page="query.page" :page-size="query.pageSize" :total="total" layout="prev, pager, next" @current-change="load" /></div></section></div>
  <el-drawer v-model="drawerOpen" title="结算与调账流水" size="560px"><template v-if="selected"><div class="drawer-title-row"><div><p class="eyebrow">DEMO SETTLEMENT</p><h2>{{ selected.orderNo }}</h2></div><el-tag type="warning">演示支付</el-tag></div><div class="finance-equation"><div><span>原始金额</span><strong>{{ money(selected.originalAmountCents) }}</strong></div><b>+</b><div><span>调账净额</span><strong>{{ money(selected.adjustmentAmountCents) }}</strong></div><b>=</b><div class="result"><span>有效应收</span><strong>{{ money(selected.effectiveAmountCents) }}</strong></div></div><el-button type="primary" class="full-button" @click="startAdjustment">新增人工调账</el-button><div class="subsection"><div class="subsection-head"><h3>不可变流水</h3><span class="muted-text">{{ selected.adjustments?.length || 0 }} 条</span></div><el-timeline v-if="selected.adjustments?.length" class="adjustment-list"><el-timeline-item v-for="item in selected.adjustments" :key="item.id" :timestamp="`${item.createdBy} · ${shanghaiTime(item.createdAt)}`" :type="item.type === 'reversal' ? 'warning' : item.amountCents < 0 ? 'success' : 'primary'"><div class="adjustment-item"><div><strong>{{ item.type === 'reversal' ? '反向撤销' : item.type === 'credit' ? '减免调账' : '补收调账' }} · {{ money(item.amountCents) }}</strong><p>{{ item.reason }}</p></div><el-button v-if="item.type !== 'reversal' && !isReversed(item)" link type="danger" @click="reverse(item)">撤销</el-button><el-tag v-else-if="isReversed(item)" type="info" size="small">已撤销</el-tag></div></el-timeline-item></el-timeline><el-empty v-else description="暂无调账流水" :image-size="76" /></div></template></el-drawer>
  <el-dialog v-model="adjustOpen" title="新增人工调账" width="520px"><el-alert title="只追加，不覆盖" description="本操作不会修改原始结算；确认后生成不可编辑、不可删除的新流水。" type="warning" :closable="false" show-icon /><el-form label-position="top" class="dialog-form"><el-form-item label="调账类型"><el-radio-group v-model="form.type"><el-radio-button value="credit">减免</el-radio-button><el-radio-button value="charge">补收</el-radio-button></el-radio-group></el-form-item><el-form-item label="金额（元）"><el-input-number v-model="form.amountYuan" :min="0" :precision="2" :step="1" controls-position="right" style="width:100%" /></el-form-item><el-form-item label="调账原因"><el-input v-model="form.reason" type="textarea" :rows="3" maxlength="160" show-word-limit /></el-form-item></el-form><div class="adjustment-preview"><span>调整前 {{ money(selected?.effectiveAmountCents || 0) }}</span><b>→</b><strong :class="{ danger: previewCents < 0 }">调整后 {{ money(previewCents) }}</strong></div><template #footer><el-button @click="adjustOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitAdjustment">下一步：二次确认</el-button></template></el-dialog>
</template>
